use std::collections::HashSet;

/// Removes duplicate integers from the input vector, preserving the order of
/// their first occurrence. The returned vector contains no duplicates, and the
/// set of its elements is equal to the set of elements in the input.
fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();

    for x in nums {
        if seen.insert(x) {
            // `insert` returns true if `x` was not present in the set yet.
            result.push(x);
        }
    }

    result
}

#[cfg(test)]
mod tests {
    use super::remove_duplicates;
    use std::collections::HashSet;

    fn vec_to_set(v: &[i32]) -> HashSet<i32> {
        v.iter().cloned().collect()
    }

    #[test]
    fn test_empty() {
        let v: Vec<i32> = vec![];
        let res = remove_duplicates(v.clone());
        assert!(res.is_empty());
        assert_eq!(vec_to_set(&res), vec_to_set(&v));
    }

    #[test]
    fn test_no_duplicates() {
        let v = vec![1, -1, 0, 42];
        let res = remove_duplicates(v.clone());
        assert_eq!(res, v);
        assert_eq!(vec_to_set(&res), vec_to_set(&v));
    }

    #[test]
    fn test_all_duplicates() {
        let v = vec![5, 5, 5, 5];
        let res = remove_duplicates(v.clone());
        assert_eq!(res, vec![5]);
        assert_eq!(vec_to_set(&res), vec_to_set(&v));
    }

    #[test]
    fn test_mixed() {
        let v = vec![3, 1, 3, 2, 1, 4, 2];
        let res = remove_duplicates(v.clone());
        // Expect first occurrences in order: 3, 1, 2, 4
        assert_eq!(res, vec![3, 1, 2, 4]);
        assert_eq!(vec_to_set(&res), vec_to_set(&v));
    }

    #[test]
    fn test_boundary_values() {
        let v = vec![i32::MIN, i32::MAX, i32::MIN, 0, i32::MAX];
        let res = remove_duplicates(v.clone());
        assert_eq!(res, vec![i32::MIN, i32::MAX, 0]);
        assert_eq!(vec_to_set(&res), vec_to_set(&v));
    }
}

fn main() {
    let input = vec![1, 2, 2, 3, 1, 4];
    let unique = remove_duplicates(input.clone());
    println!("Input: {:?}\nUnique: {:?}", input, unique);
}